const note = sticky("## SMC Vision v2 — bot ICT/SMC (COMPTE DÉMO)\n\nA chaque clôture M15, pour chaque actif :\n1. **Vision HTF** (Monthly, Weekly, Daily) : biais, dealing range (prime / décote), point B (DOL).\n2. **Setup H4** : jambe A → B qui casse la structure, point A = balayage de liquidité (AMD), retour en OTE / OB / BB / FVG / IFVG / BPR.\n3. **Confirmation H1** : rejet, CHoCH ou FVG H1 dans la zone.\n4. **Entrée M15** en killzone (Londres 02h-05h, New York 07h-11h, heure NY ; cryptos 24h/24) : balayage de liquidité, MSS avec déplacement et volume, **ordre limite au FVG** du déplacement.\n5. **Note A++** (≥ 20 points) : biais, OTE, zones, Power of 3, Judas swing, SMT, volume, RSI…\n\nRisque dégressif selon le solde, 2 pertes par jour au maximum. La gestion (break-even après TP1, stop suiveur structure M15) est faite par le workflow « SMC Vision - Gestion des trades ».\nLa raison de chaque « pas de trade » et la note sont visibles dans la sortie du nœud *Lecture ICT/SMC*.\n", [declencheur, configuration], { color: 4, width: 520, height: 520 });

export default workflow('smc-vision', 'SMC Vision - Bot ICT/SMC autonome (DEMO Fusion cTrader)')
  .add(note)
  .add(declencheur)
  .to(configuration)
  .to(solde)
  .to(positions)
  .to(ordres)
  .to(dealsJour)
  .to(dealsRecents)
  .to(journalLu)
  .to(resultats)
  .to(majJournal)
  .add(journalLu)
  .to(preparer)
  .to(boucle.onEachBatch(
    actifEnCours
      .to(bMN).to(bW1).to(bD1).to(bH4).to(bH1).to(bM15).to(bC15)
      .to(lecture)
      .to(siTrade
        .onTrue(spec.to(taille).to(siVolume
          .onTrue(placer.to(rassembler.to(journalEcrit.to(nextBatch(boucle)))))
          .onFalse(rassembler)))
        .onFalse(nextBatch(boucle)))
  ));
